import React from 'react';
import { TextField } from '@salutejs/sdds-finai';
export function App() {
    const validateChip = (value) => (value === 'Значение 1' ? { view: 'negative' } : {});
    return (
        <div>
            <TextField
                placeholder="Введите значение"
                defaultValue="Значение"
                size="s"
                enumerationType="chip"
                helperText="Подсказка снизу"
                chips={["Значение 1", "Значение 2"]}
                chipView="positive"
                chipValidator={validateChip}
            />
            <TextField
                placeholder="Введите значение"
                defaultValue="Значение"
                size="s"
                enumerationType="chip"
                helperText="Подсказка снизу"
                chips={["Значение 1"]}
                chipType="text"
            />
        </div>
    );
}

import React, { useState } from "react";
import { IconClose } from "@salutejs/plasma-icons";
import { TextField, EmbedIconButton } from '@salutejs/sdds-finai';
export function App() {
const [text, setName] = useState('');
  return (
    <div>
      <TextField
        value={text}
        label="Введите имя"
        placeholder="Например, Алексей"
        onChange={(e) => {
            setName(e.target.value);
        }}
        defaultValue=""
        contentRight={
          (text && !!text.length) && <EmbedIconButton
            size="s"
            view="secondary"
            onClick={() => {
              setName("");
            }}
          >
            <IconClose color="inherit" size="s" />
          </EmbedIconButton>
        }
      />
    </div>
  );
}

import React from "react";
import { IconLockOutline } from '@salutejs/plasma-icons';
import { TextField } from '@salutejs/sdds-finai';
export function App() {
  const isReadOnly = true;
  return (
      <TextField
        label="Введите имя"
        placeholder="Например, Алексей"
        readOnly={isReadOnly}
        defaultValue=""
        contentRight={isReadOnly && <IconLockOutline color="inherit" size="s" />}
      />
  );
}
